"""Optional Wayfarer Journal surfaces for the selected standalone game.

Keep commissions, discovered field notes and party conversations inside the
existing classic menus rather than covering the exploration playfield.
"""

HELPERS = r'''function focusWayfarerCommission(id){requestAnimationFrame(()=>{let card=Array.from(document.querySelectorAll(`#modal-root [data-commission-id]`)).find(element=>element.dataset.commissionId===id);if(card){card.focus({preventScroll:!0});card.scrollIntoView({block:`nearest`,inline:`nearest`,behavior:`instant`})}})}var wayfarerTab=`commissions`,wayfarerRegion=``;
function wayfarerRewardText(reward){let parts=[];if(reward?.gold)parts.push(`${reward.gold} gold`);for(let [id,count]of Object.entries(reward?.items||{}))if(count>0)parts.push(`${K(id)?.name||id} ×${count}`);return parts.join(` · `)||`Recognition from the road crews`}
function wayfarerJournalUI(state,board=!1){let current=wayfarerSummary(state),selected=board?current.boardRegion||current.regionId:wayfarerRegion||current.regionId,summary=wayfarerSummary(state,selected),regions=summary.regions||[],tab=wayfarerTab;return`<div class="wayfarer-journal" data-wayfarer-journal="${board?`board`:`journal`}"><nav class="wayfarer-tabs" aria-label="Wayfarer journal sections">${[[`commissions`,`Commissions`],[`bestiary`,`Bestiary`],[`tales`,`Camp tales`]].map(([id,label])=>`<button data-wayfarer-tab="${id}" aria-pressed="${tab===id}" class="${tab===id?`chosen`:``}">${label}</button>`).join(``)}</nav>${tab===`commissions`?`<p class="wayfarer-intro">Small promises make the roads safer. Accept work at a town's Wayfarer Board, explore at your own pace, then return there to collect a one-time reward.</p>${!board?`<nav class="wayfarer-regions" aria-label="Commission region">${regions.map(region=>`<button data-wayfarer-region="${Q(region.id)}" aria-pressed="${summary.regionId===region.id}" class="${summary.regionId===region.id?`chosen`:``}">${Q(region.name)}</button>`).join(``)}</nav>`:``}<div class="wayfarer-heading"><div><span class="eyebrow">REGIONAL COMMISSIONS</span><h3>${Q(summary.regionName)}</h3></div><small>${summary.contracts.filter(contract=>contract.claimed).length} / ${summary.contracts.length} delivered</small></div><div class="wayfarer-contracts">${summary.contracts.map(contract=>{let local=board&&summary.boardRegion===contract.regionId,unlocked=!!contract.available,status=contract.claimed?`Delivered`:!unlocked?`Not yet available`:contract.ready?`Ready to deliver`:contract.accepted?`In progress`:`Available`,townId=regions.find(region=>region.id===contract.regionId)?.town,town=f[townId]?.name||townId||contract.regionName;return`<article class="wayfarer-contract ${contract.claimed?`is-claimed`:contract.ready?`is-ready`:``}" data-commission-id="${Q(contract.id)}" tabindex="-1" aria-label="${Q(contract.title)}: ${status}"><header><h4>${Q(contract.title)}</h4><span class="wayfarer-badge">${status}</span></header><p>${Q(contract.description)}</p><p class="wayfarer-destination">Route: ${Q(contract.destinationName||contract.root||contract.regionName)}</p><ul class="wayfarer-progress">${(contract.progress||[]).map(goal=>`<li class="${goal.current>=goal.target?`is-done`:``}"><span>${Q(goal.label)}</span><strong>${Math.min(goal.target,Math.max(0,goal.current))} / ${goal.target}</strong></li>`).join(``)}</ul><div class="wayfarer-reward"><span>Reward</span><strong>${Q(wayfarerRewardText(contract.reward))}</strong></div>${contract.claimed?`<p class="wayfarer-complete">${Q(contract.completionText||`The road crew thanks the party. This commission is complete.`)}</p>`:local&&unlocked?`<div class="wayfarer-card-actions">${contract.accepted?`<button class="small-button" data-commission-claim="${Q(contract.id)}" ${contract.ready&&!contract.claimBlocked?``:`disabled`} ${contract.claimBlocked?`title="${Q(contract.claimBlocked)}"`:``}>${contract.ready?`Deliver commission`:`Work in progress`}</button>${contract.claimBlocked?`<p class="wayfarer-hint">${Q(contract.claimBlocked)}</p>`:``}`:`<button class="small-button" data-commission-accept="${Q(contract.id)}">Accept commission</button>`}</div>`:`<p class="wayfarer-hint">${unlocked?`Return to the Wayfarer Board in ${Q(town)} to ${contract.accepted?`deliver this work`:`accept this commission`}.`:`Continue the main journey to unlock this region's work.`}</p>`}</article>`}).join(``)}</div><p class="wayfarer-hint">Accepted patrol work counts foes defeated in future victories. Saved route discoveries also count. Commissions grant no EXP and never block the main journey.</p>`:tab===`bestiary`?`<div class="wayfarer-heading"><div><span class="eyebrow">NOTES FROM ACTUAL VICTORIES</span><h3>Know the next threat</h3></div><small>${summary.bestiary.length} ${summary.bestiary.length===1?`entry`:`entries`} · ${summary.totalDefeated} ${summary.totalDefeated===1?`foe`:`foes`} defeated</small></div><p class="wayfarer-intro">Victories add field notes. Compare weaknesses before choosing jobs, weapons and spells. Retreats and defeats do not add entries.</p>${summary.bestiary.length?`<div class="wayfarer-bestiary">${summary.bestiary.map(enemy=>`<article class="wayfarer-entry rank-${Q(enemy.rank||`base`)}" data-bestiary-key="${Q(enemy.key)}"><header><h4>${Q(enemy.name)}</h4><span class="wayfarer-badge">${Q(enemy.rank||`base`)}</span></header><p>${Q(regions.find(region=>region.id===enemy.regionId)?.name||enemy.regionId)} · ${Q(enemy.family)} · ${enemy.defeated} defeated</p><dl><div><dt>Weakness</dt><dd>${Q(enemy.weakness?.length?enemy.weakness.join(`, `):`None recorded`)}</dd></div><div><dt>Resists</dt><dd>${Q(enemy.resistance?.length?enemy.resistance.join(`, `):`None recorded`)}</dd></div></dl></article>`).join(``)}</div>`:`<div class="wayfarer-empty"><strong>The first page is still blank.</strong><p>Win an encounter on the road or in a dungeon to record its enemies here.</p></div>`}`:`<div class="wayfarer-heading"><div><span class="eyebrow">A MOMENT AT THE SHELTER</span><h3>Between the bells</h3></div></div><p class="wayfarer-intro">Return to a safe shelter and hear what the party carries beyond its equipment. Conversations open as the journey advances and can be replayed.</p><div class="wayfarer-tales">${campTales(state).map(tale=>{let unlocked=tale.unlocked??tale.available,safe=state.mode===`explore`&&!state.message&&!state.reward&&!state.battle&&p(state.area,state.player.x,state.player.y);return`<article class="wayfarer-tale" data-camp-tale-card="${Q(tale.id)}"><header><h4>${Q(tale.title)}</h4><span class="wayfarer-badge">${tale.heard?`Remembered`:unlocked?`New conversation`:`Not yet available`}</span></header><p>${Q(unlocked?tale.teaser:`Continue the main journey to discover this conversation.`)}</p><button class="small-button" data-camp-tale="${Q(tale.id)}" ${tale.available&&safe?``:`disabled`}>${tale.heard?`Hear it again`:`Sit with the party`}</button>${unlocked&&!safe?`<p class="wayfarer-hint">Find a safe shelter and finish the current conversation first.</p>`:``}</article>`}).join(``)}</div><p class="wayfarer-hint">These are conversations, not recovery actions. HP, charges and supplies stay as they are.</p>`}</div>`}
'''

CSS = r'''
.wayfarer-modal{--wf-rule:#718ac0;--wf-muted:#c7d9f6;--wf-warm:#ffdfa0;--wf-done:#bce2b6;max-width:800px}.wayfarer-tabs,.wayfarer-regions{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 15px}.wayfarer-tabs button,.wayfarer-regions button{font:inherit;font-size:12px;color:#e8efff;background:#102b70;border:1px solid var(--wf-rule);padding:9px 12px;cursor:pointer;min-height:38px}.wayfarer-tabs button.chosen,.wayfarer-regions button.chosen{background:#3456a7;border-color:#fff;box-shadow:inset 0 -2px 0 var(--wf-warm)}.wayfarer-regions button{font-size:10px;padding:7px 9px;min-height:34px}.wayfarer-intro{font-size:12px!important;line-height:1.7;color:var(--wf-muted)}.wayfarer-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin:18px 0 12px}.wayfarer-heading h3{margin:4px 0 0;font-size:18px}.wayfarer-heading>small{font-size:11px;color:var(--wf-muted);text-align:right;line-height:1.6}.wayfarer-contracts,.wayfarer-tales{display:grid;gap:13px}.wayfarer-contract,.wayfarer-tale,.wayfarer-entry{background:#10266680;border:1px solid var(--wf-rule);padding:14px;min-width:0}.wayfarer-contract>header,.wayfarer-tale>header,.wayfarer-entry>header{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.wayfarer-journal h4{font-size:14px;line-height:1.5;margin:0}.wayfarer-badge{font-size:9px;line-height:1.5;color:var(--wf-warm);border:1px solid #738bc0;padding:3px 6px;flex-shrink:0;max-width:45%;text-align:right}.wayfarer-contract.is-ready{border-color:var(--wf-warm)}.wayfarer-contract.is-claimed .wayfarer-badge{color:var(--wf-done)}.wayfarer-journal p{font-size:12px;line-height:1.7}.wayfarer-destination{color:var(--wf-muted);font-size:10px!important}.wayfarer-progress{list-style:none;padding:0;margin:13px 0}.wayfarer-progress li{display:flex;justify-content:space-between;gap:15px;padding:7px 0;border-bottom:1px solid #6077ab;font-size:11px;line-height:1.6}.wayfarer-progress strong{white-space:nowrap;font-weight:normal}.wayfarer-progress .is-done{color:var(--wf-done)}.wayfarer-reward{display:flex;justify-content:space-between;gap:14px;font-size:11px;line-height:1.7;margin:12px 0;color:var(--wf-warm)}.wayfarer-reward strong{font-weight:normal;text-align:right}.wayfarer-card-actions{display:flex;flex-direction:column;align-items:flex-end;gap:8px}.wayfarer-card-actions>.wayfarer-hint{width:100%;margin:0}.wayfarer-hint{color:var(--wf-muted);font-size:10px!important;line-height:1.7!important}.wayfarer-complete{font-size:11px!important;color:var(--wf-done)}.wayfarer-bestiary{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wayfarer-entry p{color:var(--wf-muted);font-size:10px}.wayfarer-entry dl{margin:10px 0 0;font-size:11px;line-height:1.7}.wayfarer-entry dl>div{display:flex;justify-content:space-between;gap:14px;border-top:1px solid #6077ab;padding:6px 0}.wayfarer-entry dt{color:var(--wf-muted)}.wayfarer-entry dd{margin:0;text-align:right;overflow-wrap:anywhere}.wayfarer-entry.rank-ashen{border-color:#a8a0c9}.wayfarer-entry.rank-crested,.wayfarer-entry.rank-rare{border-color:#d6ba79}.wayfarer-entry.rank-boss{border-color:#db988d}.wayfarer-empty{border:1px dashed var(--wf-rule);padding:18px;margin:18px 0}.wayfarer-empty strong{font-size:14px}.wayfarer-empty p{color:var(--wf-muted);margin-bottom:0}.wayfarer-tale .small-button{margin-top:4px}.wayfarer-journal button:focus-visible,.wayfarer-contract:focus-visible{outline:2px solid #ffe09c;outline-offset:2px}
@media(max-width:760px){.wayfarer-tabs{gap:5px}.wayfarer-tabs button{font-size:11px;padding:8px 10px;flex:1;white-space:nowrap}.wayfarer-regions{gap:5px}.wayfarer-regions button{font-size:10px;flex:1 1 28%;padding:7px}.wayfarer-heading{gap:10px}.wayfarer-heading h3{font-size:15px}.wayfarer-heading>small{font-size:10px;max-width:45%}.wayfarer-journal h4{font-size:13px}.wayfarer-contract,.wayfarer-tale,.wayfarer-entry{padding:11px}.wayfarer-badge{font-size:8px;max-width:45%}.wayfarer-journal p{font-size:11px}.wayfarer-progress li{font-size:10px;gap:10px}.wayfarer-reward{font-size:10px;gap:10px}.wayfarer-bestiary{grid-template-columns:1fr}.wayfarer-entry dl{font-size:11px}.wayfarer-intro{font-size:11px!important}}
'''


def patch(source):
    labels = []

    def once(old, new, label):
        nonlocal source
        assert source.count(old) == 1, f'{label}: expected one source anchor'
        source = source.replace(old, new, 1)
        labels.append(label)

    once('function Vt(e,t,n,r=``,i=``){', HELPERS + 'function Vt(e,t,n,r=``,i=``){',
         'optional wayfarer journal helpers for commissions discovered enemies and camp tales')
    once('[`guide`,`Journal`],[`help`,`System`]',
         '[`guide`,`Journal`],[`wayfarer`,`Wayfarer Journal`],[`help`,`System`]',
         'party menu exposes the optional wayfarer journal')
    once('let t=``,n=``;if(e.message){',
         'let t=``,n=``;if(e.message?.speaker===`Wayfarer Board`){n=`wayfarer-board:`+wayfarerSummary(e).boardRegion;if(!Ct.startsWith(`wayfarer-board:`))wayfarerTab=`commissions`;t=Vt(`Wayfarer Board`,`WORK FOR THE ROAD CREWS`,wayfarerJournalUI(e,!0),`<button class="primary" data-command="dismiss">Leave the board <span>↵</span></button>`,`wayfarer-modal`)}else if(e.message){',
         'local board opens commissions through the existing dialogue flow')
    once('}else mt===`menu`?(n=`menu`,',
         '}else mt===`wayfarer`?(n=`wayfarer`,t=Vt(`Wayfarer Journal`,`PROMISES AND FIELD NOTES`,wayfarerJournalUI(e),``,`wayfarer-modal`)):mt===`menu`?(n=`menu`,',
         'wayfarer journal uses the normal modal and focus boundaries')
    once('if(t.dataset.panel){It(t.dataset.panel);return}',
         'if(t.dataset.wayfarerTab){wayfarerTab=t.dataset.wayfarerTab,Ht();return}if(t.dataset.wayfarerRegion){wayfarerRegion=t.dataset.wayfarerRegion,Ht();return}if(t.dataset.commissionAccept){Pt(X.acceptCommission(t.dataset.commissionAccept)?`Commission accepted. Its progress is saved in the Wayfarer Journal.`:`Accept this work at its local Wayfarer Board.`),Gt(),focusWayfarerCommission(t.dataset.commissionAccept);return}if(t.dataset.commissionClaim){Pt(X.claimCommission(t.dataset.commissionClaim)?`Commission delivered. The road crew added your reward to the shared pack.`:`Finish the objectives and return to this region’s Wayfarer Board.`),Gt(),focusWayfarerCommission(t.dataset.commissionClaim);return}if(t.dataset.campTale){let heard=X.hearCampTale(t.dataset.campTale);if(heard)mt=null;else Pt(`Find a safe shelter and finish the current conversation first.`);Gt();return}if(t.dataset.panel){if(t.dataset.panel===`wayfarer`){wayfarerTab=`commissions`;wayfarerRegion=``}It(t.dataset.panel);return}',
         'journal tabs and local commission actions preserve engine authority')
    once('if(!Ot&&e.key===`Escape`&&[`Quartermaster`,`Weapon Shop`,`Item Shop`,`Magic Shop`].includes(X.state.message?.speaker)){',
         'if(!Ot&&e.key===`Escape`&&[`Quartermaster`,`Weapon Shop`,`Item Shop`,`Magic Shop`,`Wayfarer Board`].includes(X.state.message?.speaker)){',
         'Escape leaves the notice board through the ordinary dialogue dismissal')
    once('${mt?`<button data-close aria-label="Close panel" class="close-button">×</button>`:``}</div>${n}',
         '${X.state.message?.speaker===`Wayfarer Board`?`<button data-board-close aria-label="Leave notice board" class="close-button">×</button>`:mt?`<button data-close aria-label="Close panel" class="close-button">×</button>`:``}</div>${n}',
         'notice boards provide a top close button for touch players')
    once('if(t.hasAttribute(`data-close`)){mt=null,Ht();return}',
         'if(t.hasAttribute(`data-board-close`)){X.dismiss();return}if(t.hasAttribute(`data-close`)){mt=null,Ht();return}',
         'board close button dismisses its message without altering other panels')
    once('</head>', '<style>' + CSS + '</style>\n</head>',
         'responsive classic journal windows keep secondary goals off the playfield')
    return source, labels
